    import sys
    import heapq

    def find(parent, x):
        if parent[x] != x:
            parent[x] = find(parent, parent[x])
        return parent[x]

    def union(parent, rank, x, y):
        rootX = find(parent, x)
        rootY = find(parent, y)

        if rootX != rootY:
            if rank[rootX] > rank[rootY]:
                parent[rootY] = rootX
            elif rank[rootX] < rank[rootY]:
                parent[rootX] = rootY
            else:
                parent[rootY] = rootX
                rank[rootX] += 1

    def can_pave_sunny_paving(n, edges):
        parent = list(range(n + 1))
        rank = [0] * (n + 1)
        degree = [0] * (n + 1)
        max_length = 0

        for u, v, w in edges:
            rootU = find(parent, u)
            rootV = find(parent, v)

            if rootU != rootV:
                union(parent, rank, rootU, rootV)
                degree[u] += 1
                degree[v] += 1
                max_length = max(max_length, w)

        # Check if all nodes have odd degree
        for d in degree[1:]:
            if d % 2 == 0:
                return -1

        return max_length

    def process_queries(n, m, queries):
        edges = []
        results = []

        for u, v, w in queries:
            edges.append((u, v, w))
            result = can_pave_sunny_paving(n, edges)
            results.append(result)

        return results

    # Read input
    n, m = map(int, sys.stdin.readline().split())
    queries = [tuple(map(int, sys.stdin.readline().split())) for _ in range(m)]

    # Process queries and print results
    results = process_queries(n, m, queries)
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
